import "server-only";
import Anthropic from "@anthropic-ai/sdk";
import { captionPrompt, parseCopyJson, templateCopy, type PostCopy } from "@/lib/domain/captions";
import type { BrandProfile, Platform } from "@/lib/domain/types";

/**
 * Caption adapter. Order of preference:
 *   1. copy already generated by the bridge on the editing PC (Claude Code, no paid API), stored on the post;
 *   2. this server generator, only when ANTHROPIC_API_KEY is set (explicit "Regenerate" or full-auto);
 *   3. the deterministic template (job title + brand CTA/hashtags), always editable.
 */
export function serverCaptionsEnabled(): boolean {
  return Boolean(process.env.ANTHROPIC_API_KEY);
}

export async function generateCopy(input: {
  platform: Platform;
  jobTitle: string;
  brand: BrandProfile;
  workspaceName: string;
  notes?: string | null;
}): Promise<{ copy: PostCopy; source: "server" | "template" }> {
  if (!serverCaptionsEnabled()) return { copy: templateCopy(input.platform, input.jobTitle, input.brand), source: "template" };
  try {
    const client = new Anthropic();
    const response = await client.messages.create({
      model: process.env.ANTHROPIC_CAPTION_MODEL || "claude-opus-5-5",
      max_tokens: 2000,
      output_config: { effort: "low" },
      messages: [{ role: "user", content: captionPrompt(input) }],
    });
    if (response.stop_reason === "refusal") throw new Error("Caption request declined.");
    const text = response.content.map((b) => (b.type === "text" ? b.text : "")).join("");
    const copy = parseCopyJson(text);
    if (copy) return { copy, source: "server" };
  } catch (e) {
    console.error("caption generation failed", (e as Error).message);
  }
  return { copy: templateCopy(input.platform, input.jobTitle, input.brand), source: "template" };
}
